<script setup lang="ts">
import {ref} from 'vue';import {KeyRound,ArrowRight} from 'lucide-vue-next';import Brand from '../../components/Brand.vue';import {authenticate,type Session} from '../../api/endpoints';import {message} from '../../api/client'
const props=defineProps<{session:Session}>();const emit=defineEmits<{ready:[]}>();const password=ref(''),code=ref(''),error=ref(''),busy=ref(false)
async function submit(){busy.value=true;error.value='';try{await authenticate(props.session.needs_setup,password.value,code.value||undefined);password.value='';code.value='';emit('ready')}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><main class="auth"><Brand/><section><div class="eyebrow"><KeyRound :size="16"/>管理控制台</div><h1>{{session.needs_setup?'设置管理员密码':'管理员登录'}}</h1><form @submit.prevent="submit"><label v-if="session.setup_code_required">首次设置验证码<input v-model.trim="code" required autocomplete="one-time-code"/><small>在测试实例的启动日志中查看。</small></label><label>管理员密码<input v-model="password" type="password" required :minlength="session.needs_setup?10:1" :autocomplete="session.needs_setup?'new-password':'current-password'"/><small v-if="session.needs_setup">至少 10 个字符，最多 72 字节。</small></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy">{{busy?'正在验证':session.needs_setup?'设置并登录':'登录'}}<ArrowRight/></button></form></section><small class="mono">NOVA · v{{session.version}}</small></main></template>
<style scoped>.auth{max-width:440px;margin:0 auto;padding:clamp(48px,13vh,140px) var(--space-6) var(--space-8)}section{margin:var(--space-10) 0 var(--space-8)}h1{margin:var(--space-3) 0 var(--space-6)}.eyebrow{display:flex;align-items:center;gap:var(--space-2);color:var(--md-on-surface-variant)}section button{height:44px}</style>
